-- Match current entity mappings, including inherited audit columns.
-- UUID identifiers are generated by Hibernate.

CREATE TABLE public.addresses (
    id uuid PRIMARY KEY,
    is_default boolean,
    district varchar(255) NOT NULL,
    province varchar(255) NOT NULL,
    recipient_name varchar(255) NOT NULL,
    recipient_phone varchar(255) NOT NULL,
    street_detail varchar(255),
    ward varchar(255) NOT NULL,
    user_id uuid,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT fk_addresses_user FOREIGN KEY (user_id) REFERENCES public.users (id)
);

CREATE TABLE public.payment_group (
    id uuid PRIMARY KEY,
    name varchar(100) NOT NULL,
    code varchar(100) NOT NULL,
    sort_order integer,
    status integer,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT uq_payment_group_code UNIQUE (code)
);

CREATE TABLE public.payment_method (
    id uuid PRIMARY KEY,
    name varchar(150) NOT NULL,
    code varchar(100) NOT NULL,
    status integer,
    icon varchar(255),
    type integer,
    can_view_anonymous boolean NOT NULL DEFAULT false,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT uq_payment_method_code UNIQUE (code)
);

CREATE TABLE public.group_payment_method (
    id uuid PRIMARY KEY,
    group_id uuid,
    method_id uuid,
    discount_percent numeric(5, 2),
    max_discount_amount numeric(15, 2),
    min_amount numeric(38, 2),
    extra_fee_percent numeric(38, 2),
    extra_fee_amount numeric(38, 2),
    description varchar(255),
    version bigint,
    sort_order integer,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT uk_group_payment_method UNIQUE (group_id, method_id),
    CONSTRAINT fk_group_payment_method_group FOREIGN KEY (group_id) REFERENCES public.payment_group (id),
    CONSTRAINT fk_group_payment_method_method FOREIGN KEY (method_id) REFERENCES public.payment_method (id)
);

CREATE TABLE public.orders (
    id uuid PRIMARY KEY,
    user_id uuid,
    address_id uuid,
    order_code varchar(255) NOT NULL,
    total_amount numeric(38, 2),
    discount_amount numeric(38, 2),
    shipping_fee numeric(38, 2),
    final_amount numeric(38, 2),
    order_status integer,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT uq_orders_order_code UNIQUE (order_code),
    CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES public.users (id),
    CONSTRAINT fk_orders_address FOREIGN KEY (address_id) REFERENCES public.addresses (id)
);

CREATE TABLE public.order_details (
    id uuid PRIMARY KEY,
    order_id uuid,
    product_id uuid,
    quantity integer NOT NULL,
    unit_price numeric(38, 2) NOT NULL,
    sub_total numeric(38, 2) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT fk_order_details_order FOREIGN KEY (order_id) REFERENCES public.orders (id),
    CONSTRAINT fk_order_details_product FOREIGN KEY (product_id) REFERENCES public.products (id),
    CONSTRAINT ck_order_details_quantity CHECK (quantity > 0),
    CONSTRAINT ck_order_details_unit_price CHECK (unit_price >= 0),
    CONSTRAINT ck_order_details_sub_total CHECK (sub_total >= 0)
);

CREATE TABLE public.payments (
    id uuid PRIMARY KEY,
    order_id uuid,
    payment_method_id uuid NOT NULL,
    payment_code varchar(100) NOT NULL,
    amount numeric(15, 2) NOT NULL,
    status varchar(30) NOT NULL,
    paid_at timestamp(6) with time zone,
    expires_at timestamp(6) with time zone,
    failure_reason varchar(500),
    created_at timestamp(6) with time zone NOT NULL,
    created_by varchar(255),
    last_modified_at timestamp(6) with time zone NOT NULL,
    last_modified_by varchar(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT uq_payments_payment_code UNIQUE (payment_code),
    CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES public.orders (id),
    CONSTRAINT fk_payments_method FOREIGN KEY (payment_method_id) REFERENCES public.payment_method (id),
    CONSTRAINT ck_payments_amount CHECK (amount >= 0),
    CONSTRAINT ck_payments_status CHECK (status IN ('PENDING', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'EXPIRED'))
);

CREATE INDEX idx_addresses_user_id
    ON public.addresses (user_id);

CREATE INDEX idx_group_payment_method_method_id
    ON public.group_payment_method (method_id);

CREATE INDEX idx_orders_user_id
    ON public.orders (user_id);

CREATE INDEX idx_orders_address_id
    ON public.orders (address_id);

CREATE INDEX idx_order_details_order_id
    ON public.order_details (order_id);

CREATE INDEX idx_order_details_product_id
    ON public.order_details (product_id);

CREATE INDEX idx_payments_order_id
    ON public.payments (order_id);

CREATE INDEX idx_payments_payment_method_id
    ON public.payments (payment_method_id);
